import java.util.Date;
import java.util.List;
import java.util.ArrayList;

// 1. Class is final to prevent extension
public final class ImmutableUserSession {

    // 2. All fields are private and final
    private final String sessionId;
    private final Date loginTime; // Mutable object
    private final List<String> roles; // Mutable collection

    public ImmutableUserSession(String sessionId, Date loginTime, List<String> roles) {
        this.sessionId = sessionId;

        // 3. Defensive copy of mutable Date (Do not use loginTime.clone() if Date can be subclassed)
        if (loginTime == null) {
            throw new IllegalArgumentException("Login time cannot be null");
        }
        this.loginTime = new Date(loginTime.getTime());

        // 4. Defensive copy of collection using Java 10+ List.copyOf (creates an unmodifiable copy)
        if (roles == null) {
            throw new IllegalArgumentException("Roles cannot be null");
        }
        this.roles = List.copyOf(roles);
    }

    public String getSessionId() {
        return sessionId; // Safe: String is inherently immutable
    }

    // 5. Defensive copy on accessor to prevent state leak
    public Date getLoginTime() {
        return new Date(this.loginTime.getTime());
    }

    // 6. Safe to return directly because List.copyOf guarantees the list is unmodifiable
    public List<String> getRoles() {
        return roles;
    }
}
